-- QA semantic embeddings generated from QA.csv
-- Model: sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2 (384 dimensions; normalized)
-- Run in the Supabase SQL Editor. Query vectors must use the same model.
create extension if not exists vector with schema extensions;

create table if not exists public.qa (
  id bigint generated always as identity primary key,
  question text not null unique,
  answer text not null,
  embedding extensions.vector(384) not null
);

create index if not exists qa_embedding_hnsw_idx
  on public.qa using hnsw (embedding vector_cosine_ops);

on conflict (question) do update set answer = excluded.answer, embedding = excluded.embedding;

create or replace function public.match_qa (
  query_embedding extensions.vector(384),
  match_count int default 5
) returns table (id bigint, question text, answer text, similarity float)
language sql stable as $$
  select qa.id, qa.question, qa.answer,
         1 - (qa.embedding <=> query_embedding) as similarity
  from public.qa
  order by qa.embedding <=> query_embedding
  limit least(greatest(match_count, 1), 100);
$$;
